// services/myJugglerVCalculator.ts
import type { MyJugglerVInput, MyJugglerVSettingProbabilities, MyJugglerVFullResult, MyJugglerVProbabilitiesBreakdown, ObservedRates } from '../types';
import { 
  MyJugglerVSetting,
  MY_JUGGLER_V_SETTINGS_NAMES,
  MY_JUGGLER_V_IDEAL_RATES,
} from '../constants/myJugglerVConstants';

const MIN_LIKELIHOOD = 1e-10;

const normalizeProbabilities = (probs: MyJugglerVSettingProbabilities): MyJugglerVSettingProbabilities => {
  const normalized: MyJugglerVSettingProbabilities = {};
  let total = Object.values(probs).reduce((sum, p) => sum + p, 0);

  if (total === 0 || isNaN(total) || !isFinite(total)) {
    const numSettings = Object.keys(probs).length;
    const val = numSettings > 0 ? 1 / numSettings : 0;
    for (const key in probs) {
      normalized[key] = val;
    }
  } else {
    for (const key in probs) {
      normalized[key] = probs[key] / total;
    }
  }
  return normalized;
};

function getLogLikelihoodForBinomial(k: number, n: number, p: number): number {
  if (p < 0 || p > 1) return -Infinity;
  if (k < 0 || n < 0 || k > n) return -Infinity;
  if (n === 0) return (k === 0) ? 0 : -Infinity; 
  if (p === 0) return (k === 0) ? 0 : -Infinity; 
  if (p === 1) return (k === n) ? 0 : -Infinity; 

  let logL = 0;
  if (k > 0) logL += k * Math.log(p);
  if (n - k > 0) logL += (n - k) * Math.log(1 - p);

  return isFinite(logL) ? logL : -Infinity;
}

export const calculateMyJugglerVProbabilities = (
  inputs: MyJugglerVInput
): MyJugglerVFullResult => {
  const overallLikelihoods: MyJugglerVSettingProbabilities = {};
  const breakdownLikelihoods: MyJugglerVProbabilitiesBreakdown = {};
  const observedRates: ObservedRates = {};
  const activeElementKeysForDisplay = new Set<string>();

  const allPossibleElementNames = [
    "BIG確率", "REG確率", 
    "単独BIG確率", "チェリーBIG確率", "レア役BIG確率",
    "単独REG確率", "チェリーREG確率",
    "ブドウ🍇 確率", "非重複チェリー🍒 確率",
    "開始時データ"
  ];
  allPossibleElementNames.forEach(name => breakdownLikelihoods[name] = {});

  MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
    overallLikelihoods[setting] = 1.0;
    allPossibleElementNames.forEach(name => breakdownLikelihoods[name][setting] = 1.0);
  });

  const { 
    bellCount: grapeCount,
    nonDuplicateCherryCount,
    soloBigCount,
    cherryBigCount,
    rareBigCount,
    soloRegCount,
    cherryRegCount
  } = inputs;

  const playedGames = inputs.currentTotalGames - inputs.startTotalGames;

  // Use trigger totals if general data counts are zero or smaller than the detailed triggers
  const triggerBigTotal = soloBigCount + cherryBigCount + rareBigCount;
  const triggerRegTotal = soloRegCount + cherryRegCount;
  const playedBigCount = Math.max(inputs.currentBigCount - inputs.startBigCount, triggerBigTotal);
  const playedRegCount = Math.max(inputs.currentRegCount - inputs.startRegCount, triggerRegTotal);

  const addObservedRate = (element: string, count: number, trials: number, ratePrefix: string = "1/", precision: number = 1) => {
    if (trials > 0 && count >= 0) {
      observedRates[element] = count > 0 ? `${ratePrefix}${(trials / count).toFixed(precision)}` : "-";
      activeElementKeysForDisplay.add(element);
    } else if (count > 0 && trials <=0) {
      observedRates[element] = "-";
      activeElementKeysForDisplay.add(element);
    } else if (element === "開始時データ" && inputs.startTotalGames > 0) {
       const startTotalBonuses = inputs.startBigCount + inputs.startRegCount;
       observedRates[element] = startTotalBonuses > 0 ? `1/${(inputs.startTotalGames / startTotalBonuses).toFixed(1)}` : "-";
       activeElementKeysForDisplay.add(element);
    } else {
      observedRates[element] = "-";
    }
  };

  addObservedRate("BIG確率", playedBigCount, playedGames);
  addObservedRate("REG確率", playedRegCount, playedGames);
  addObservedRate("単独BIG確率", soloBigCount, playedGames);
  addObservedRate("チェリーBIG確率", cherryBigCount, playedGames);
  addObservedRate("レア役BIG確率", rareBigCount, playedGames);
  addObservedRate("単独REG確率", soloRegCount, playedGames);
  addObservedRate("チェリーREG確率", cherryRegCount, playedGames);
  addObservedRate("ブドウ🍇 確率", grapeCount, playedGames, "1/", 2);
  addObservedRate("非重複チェリー🍒 確率", nonDuplicateCherryCount, playedGames);
  addObservedRate("開始時データ", inputs.startBigCount + inputs.startRegCount, inputs.startTotalGames);

  const useSpecificBigTriggers = (soloBigCount > 0 || cherryBigCount > 0 || rareBigCount > 0) && playedGames > 0;
  const useSpecificRegTriggers = (soloRegCount > 0 || cherryRegCount > 0) && playedGames > 0;

  // --- Likelihood Calculation Loop ---
  allPossibleElementNames.forEach(elementName => {
    const tempLogLikelihoods: MyJugglerVSettingProbabilities = {};
    MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
      const idealRates = MY_JUGGLER_V_IDEAL_RATES[setting as MyJugglerVSetting];
      let logL = 0; 
      let k = 0, n = 0, p = 0;

      switch (elementName) {
        case "BIG確率": 
          k = playedBigCount; n = playedGames; 
          p = idealRates.totalBig; 
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "REG確率": 
          k = playedRegCount; n = playedGames; 
          p = (idealRates.soloReg + idealRates.cherryReg); 
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "単独BIG確率":
          k = soloBigCount; n = playedGames; p = idealRates.soloBig;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "チェリーBIG確率":
          k = cherryBigCount; n = playedGames; p = idealRates.cherryBig;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "レア役BIG確率":
          k = rareBigCount; n = playedGames; p = idealRates.rareBig;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "単独REG確率":
          k = soloRegCount; n = playedGames; p = idealRates.soloReg;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "チェリーREG確率":
          k = cherryRegCount; n = playedGames; p = idealRates.cherryReg;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "ブドウ🍇 確率":
          k = grapeCount; n = playedGames; p = idealRates.grape;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "非重複チェリー🍒 確率":
          k = nonDuplicateCherryCount; n = playedGames; p = idealRates.nonDuplicateCherry;
          if (n >= 0 && k>=0) logL = getLogLikelihoodForBinomial(k,n,p); else logL = (k > 0 && n <=0 ? -Infinity: 0);
          break;
        case "開始時データ":
          if (inputs.startTotalGames > 0) {
            const logLBigStart = getLogLikelihoodForBinomial(inputs.startBigCount, inputs.startTotalGames, idealRates.totalBig);
            const logLRegStart = getLogLikelihoodForBinomial(inputs.startRegCount, inputs.startTotalGames, (idealRates.soloReg + idealRates.cherryReg));
            if (isFinite(logLBigStart) && isFinite(logLRegStart)) {
              logL = logLBigStart + logLRegStart;
            } else {
              logL = -Infinity;
            }
          } else {
            logL = 0;
          }
          break;
      }
      tempLogLikelihoods[setting] = logL;
    });

    const maxLogL = Math.max(...Object.values(tempLogLikelihoods).filter(isFinite));

    if (isFinite(maxLogL)) {
        MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
            if (isFinite(tempLogLikelihoods[setting])) {
                breakdownLikelihoods[elementName][setting] = Math.exp(tempLogLikelihoods[setting] - maxLogL);
            } else {
                 breakdownLikelihoods[elementName][setting] = 0; 
            }
            const isElementConsideredActiveForContribution = 
                (elementName === "BIG確率" && playedBigCount > 0 && playedGames > 0 && !useSpecificBigTriggers) ||
                (elementName === "REG確率" && playedRegCount > 0 && playedGames > 0 && !useSpecificRegTriggers) ||
                (elementName === "単独BIG確率" && soloBigCount > 0 && playedGames > 0) ||
                (elementName === "チェリーBIG確率" && cherryBigCount > 0 && playedGames > 0) ||
                (elementName === "レア役BIG確率" && rareBigCount > 0 && playedGames > 0) ||
                (elementName === "単独REG確率" && soloRegCount > 0 && playedGames > 0) ||
                (elementName === "チェリーREG確率" && cherryRegCount > 0 && playedGames > 0) ||
                (elementName === "ブドウ🍇 確率" && grapeCount > 0 && playedGames > 0) ||
                (elementName === "非重複チェリー🍒 確率" && nonDuplicateCherryCount > 0 && playedGames > 0) ||
                (elementName === "開始時データ" && inputs.startTotalGames > 0);

            if (breakdownLikelihoods[elementName][setting] < MIN_LIKELIHOOD && isElementConsideredActiveForContribution) {
                 breakdownLikelihoods[elementName][setting] = MIN_LIKELIHOOD;
            } else if (!isElementConsideredActiveForContribution) {
                 breakdownLikelihoods[elementName][setting] = 1.0; 
            }
        });
    } else { 
        MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
            const isElementConsideredActiveForContribution = 
                (elementName === "BIG確率" && playedBigCount > 0 && playedGames > 0 && !useSpecificBigTriggers) ||
                (elementName === "REG確率" && playedRegCount > 0 && playedGames > 0 && !useSpecificRegTriggers) ||
                (elementName === "単独BIG確率" && soloBigCount > 0 && playedGames > 0) ||
                (elementName === "チェリーBIG確率" && cherryBigCount > 0 && playedGames > 0) ||
                (elementName === "レア役BIG確率" && rareBigCount > 0 && playedGames > 0) ||
                (elementName === "単独REG確率" && soloRegCount > 0 && playedGames > 0) ||
                (elementName === "チェリーREG確率" && cherryRegCount > 0 && playedGames > 0) ||
                (elementName === "ブドウ🍇 確率" && grapeCount > 0 && playedGames > 0) ||
                (elementName === "非重複チェリー🍒 確率" && nonDuplicateCherryCount > 0 && playedGames > 0) ||
                (elementName === "開始時データ" && inputs.startTotalGames > 0);
            breakdownLikelihoods[elementName][setting] = isElementConsideredActiveForContribution ? 0 : 1.0;
        });
    }
    breakdownLikelihoods[elementName] = normalizeProbabilities(breakdownLikelihoods[elementName]);
  });

  const contributingElementKeys = new Set<string>();
  if (grapeCount > 0 && playedGames > 0) contributingElementKeys.add("ブドウ🍇 確率");
  if (nonDuplicateCherryCount > 0 && playedGames > 0) contributingElementKeys.add("非重複チェリー🍒 確率");
  if (inputs.startTotalGames > 0) contributingElementKeys.add("開始時データ");

  if (useSpecificBigTriggers) {
    if (soloBigCount > 0) contributingElementKeys.add("単独BIG確率");
    if (cherryBigCount > 0) contributingElementKeys.add("チェリーBIG確率");
    if (rareBigCount > 0) contributingElementKeys.add("レア役BIG確率");
  } else if (playedBigCount > 0 && playedGames > 0) {
    contributingElementKeys.add("BIG確率");
  }

  if (useSpecificRegTriggers) {
    if (soloRegCount > 0) contributingElementKeys.add("単独REG確率");
    if (cherryRegCount > 0) contributingElementKeys.add("チェリーREG確率");
  } else if (playedRegCount > 0 && playedGames > 0) {
    contributingElementKeys.add("REG確率");
  }

  MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
    let product = 1.0;
    contributingElementKeys.forEach(elementName => { 
      product *= (breakdownLikelihoods[elementName]?.[setting] ?? MIN_LIKELIHOOD); 
    });
    overallLikelihoods[setting] = product;
  });

  const finalOverallProbabilities = normalizeProbabilities(overallLikelihoods);
  if (Object.values(finalOverallProbabilities).every(p => p === 0) && MY_JUGGLER_V_SETTINGS_NAMES.length > 0) {
      const uniformProb = 1 / MY_JUGGLER_V_SETTINGS_NAMES.length;
      MY_JUGGLER_V_SETTINGS_NAMES.forEach(s => finalOverallProbabilities[s] = uniformProb);
  }

  const finalResult: MyJugglerVFullResult = {
    overallProbabilities: finalOverallProbabilities,
    breakdownProbabilities: breakdownLikelihoods, 
    activeElementKeys: [...contributingElementKeys].sort((a,b) => allPossibleElementNames.indexOf(a) - allPossibleElementNames.indexOf(b)), 
  };

  if (Object.keys(observedRates).length > 0 && Object.values(observedRates).some(rate => rate !== "-")) {
    finalResult.observedRates = observedRates;
  }

  // Calculate estimated payout
  if (inputs.currentNetMedals !== null && playedGames > 0) {
    finalResult.estimatedPayout = inputs.currentNetMedals;
  } else if (playedGames > 0) {
    const replayCount = playedGames / 7.3;
    const investment = playedGames * 3;

    let grapeCountForCalc = inputs.bellCount;
    if (inputs.bellCount <= 0) {
        grapeCountForCalc = playedGames * MY_JUGGLER_V_IDEAL_RATES[MyJugglerVSetting.SETTING_1].grape;
    }

    const totalCherryCountFromInput = inputs.nonDuplicateCherryCount + inputs.cherryBigCount + inputs.cherryRegCount;
    let cherryCountForCalc = totalCherryCountFromInput;
    if (totalCherryCountFromInput <= 0) {
        cherryCountForCalc = playedGames * MY_JUGGLER_V_IDEAL_RATES[MyJugglerVSetting.SETTING_1].nonDuplicateCherry;
    }

    // My Juggler V: BIG 240, REG 96
    const payoutValue = (240 * playedBigCount) + 
                        (96 * playedRegCount) + 
                        (8 * grapeCountForCalc) + 
                        (2 * cherryCountForCalc) + 
                        (3 * replayCount);
    finalResult.estimatedPayout = payoutValue - investment;
  } else {
    finalResult.estimatedPayout = null;
  }

  return finalResult;
};

// services/jugglerSeriesCalculator.ts
import type { MyJugglerVInput, KingHanaHanaSSettingProbabilities, MyJugglerVFullResult, MyJugglerVProbabilitiesBreakdown, ObservedRates } from '../types';
import { GameMode } from '../types';
import { MY_JUGGLER_V_SETTINGS_NAMES } from '../constants/myJugglerVConstants';
import { IM_JUGGLER_EX_IDEAL_RATES } from '../constants/imJugglerExConstants';
import { GOGO_JUGGLER_3_IDEAL_RATES } from '../constants/gogoJuggler3Constants';
import { KingHanaHanaSetting } from '../constants/kingHanaHanaSConstants';

const MIN_LIKELIHOOD = 1e-10;

const normalizeProbabilities = (probs: KingHanaHanaSSettingProbabilities): KingHanaHanaSSettingProbabilities => {
  const normalized: KingHanaHanaSSettingProbabilities = {};
  let total = Object.values(probs).reduce((sum, p) => sum + p, 0);

  if (total === 0 || isNaN(total) || !isFinite(total)) {
    const numSettings = Object.keys(probs).length;
    const val = numSettings > 0 ? 1 / numSettings : 0;
    for (const key in probs) {
      normalized[key] = val;
    }
  } else {
    for (const key in probs) {
      normalized[key] = (probs[key] as number) / total;
    }
  }
  return normalized;
};

function getLogLikelihoodForBinomial(k: number, n: number, p: number): number {
  if (p <= 0 || p >= 1) return -Infinity;
  if (k < 0 || n < 0 || k > n) return -Infinity;
  if (n === 0) return (k === 0) ? 0 : -Infinity; 
  let logL = 0;
  if (k > 0) logL += k * Math.log(p);
  if (n - k > 0) logL += (n - k) * Math.log(1 - p);
  return isFinite(logL) ? logL : -Infinity;
}

export const calculateJugglerSeriesProbabilities = (
  gameMode: GameMode,
  inputs: MyJugglerVInput
): MyJugglerVFullResult => {
  const overallLikelihoods: KingHanaHanaSSettingProbabilities = {};
  const breakdownLikelihoods: MyJugglerVProbabilitiesBreakdown = {};
  const observedRates: ObservedRates = {};

  const isIm = gameMode === GameMode.IM_JUGGLER_EX;
  const isGogo = gameMode === GameMode.GOGO_JUGGLER_3;

  const allPossibleElementNames = [
    "BIG確率", "REG確率", 
    "単独BIG確率", "チェリーBIG確率", "レア役BIG確率",
    "単独REG確率", "チェリーREG確率",
    "ブドウ🍇 確率", "非重複チェリー🍒 確率",
    "開始時データ"
  ];
  allPossibleElementNames.forEach(name => breakdownLikelihoods[name] = {});

  MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
    overallLikelihoods[setting] = 1.0;
    allPossibleElementNames.forEach(name => breakdownLikelihoods[name][setting] = 1.0);
  });

  const playedGames = inputs.currentTotalGames - inputs.startTotalGames;
  const { bellCount: grapeCount, nonDuplicateCherryCount, soloBigCount, cherryBigCount, rareBigCount, soloRegCount, cherryRegCount } = inputs;

  // Use trigger totals if general data counts are zero or smaller than the detailed triggers
  const triggerBigTotal = soloBigCount + cherryBigCount + rareBigCount;
  const triggerRegTotal = soloRegCount + cherryRegCount;
  const playedBigCount = Math.max(inputs.currentBigCount - inputs.startBigCount, triggerBigTotal);
  const playedRegCount = Math.max(inputs.currentRegCount - inputs.startRegCount, triggerRegTotal);

  const useSpecificBigTriggers = (soloBigCount > 0 || cherryBigCount > 0 || rareBigCount > 0) && playedGames > 0;
  const useSpecificRegTriggers = !isGogo && (soloRegCount > 0 || cherryRegCount > 0) && playedGames > 0;

  MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
    const idealTable = isIm ? IM_JUGGLER_EX_IDEAL_RATES : GOGO_JUGGLER_3_IDEAL_RATES;
    const rates = idealTable[setting];

    allPossibleElementNames.forEach(elementName => {
      let logL = 0;
      switch (elementName) {
        case "BIG確率": logL = getLogLikelihoodForBinomial(playedBigCount, playedGames, rates.totalBig); break;
        case "REG確率": 
            const regP = isGogo ? (rates as any).reg : ((rates as any).soloReg + (rates as any).cherryReg);
            logL = getLogLikelihoodForBinomial(playedRegCount, playedGames, regP); 
            break;
        case "単独BIG確率": logL = getLogLikelihoodForBinomial(soloBigCount, playedGames, (rates as any).soloBig); break;
        case "チェリーBIG確率": logL = getLogLikelihoodForBinomial(cherryBigCount, playedGames, (rates as any).cherryBig); break;
        case "レア役BIG確率": logL = getLogLikelihoodForBinomial(rareBigCount, playedGames, (rates as any).rareBig); break;
        case "単独REG確率": if(!isGogo) logL = getLogLikelihoodForBinomial(soloRegCount, playedGames, (rates as any).soloReg); break;
        case "チェリーREG確率": if(!isGogo) logL = getLogLikelihoodForBinomial(cherryRegCount, playedGames, (rates as any).cherryReg); break;
        case "ブドウ🍇 確率": logL = getLogLikelihoodForBinomial(grapeCount, playedGames, rates.grape); break;
        case "非重複チェリー🍒 確率": if(!isIm) logL = getLogLikelihoodForBinomial(nonDuplicateCherryCount, playedGames, (rates as any).nonDuplicateCherry); break;
        case "開始時データ":
          if (inputs.startTotalGames > 0) {
            const startBigL = getLogLikelihoodForBinomial(inputs.startBigCount, inputs.startTotalGames, rates.totalBig);
            const regPStart = isGogo ? (rates as any).reg : ((rates as any).soloReg + (rates as any).cherryReg);
            const startRegL = getLogLikelihoodForBinomial(inputs.startRegCount, inputs.startTotalGames, regPStart);
            logL = (isFinite(startBigL) && isFinite(startRegL)) ? startBigL + startRegL : -Infinity;
          }
          break;
      }
      breakdownLikelihoods[elementName][setting] = logL;
    });
  });

  const contributingElementKeys = new Set<string>();
  if (grapeCount > 0 && playedGames > 0) contributingElementKeys.add("ブドウ🍇 確率");
  if (!isIm && nonDuplicateCherryCount > 0 && playedGames > 0) contributingElementKeys.add("非重複チェリー🍒 確率");
  if (inputs.startTotalGames > 0) contributingElementKeys.add("開始時データ");
  if (useSpecificBigTriggers) {
    if (soloBigCount > 0) contributingElementKeys.add("単独BIG確率");
    if (cherryBigCount > 0) contributingElementKeys.add("チェリーBIG確率");
    if (rareBigCount > 0) contributingElementKeys.add("レア役BIG確率");
  } else if (playedBigCount > 0 && playedGames > 0) {
    contributingElementKeys.add("BIG確率");
  }
  if (useSpecificRegTriggers) {
    if (soloRegCount > 0) contributingElementKeys.add("単独REG確率");
    if (cherryRegCount > 0) contributingElementKeys.add("チェリーREG確率");
  } else if (playedRegCount > 0 && playedGames > 0) {
    contributingElementKeys.add("REG確率");
  }

  allPossibleElementNames.forEach(elementName => {
    const tempLog = breakdownLikelihoods[elementName];
    const maxLogL = Math.max(...Object.values(tempLog).filter(isFinite));
    MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
      if (isFinite(tempLog[setting])) {
        breakdownLikelihoods[elementName][setting] = Math.exp(tempLog[setting] - maxLogL);
      } else {
        breakdownLikelihoods[elementName][setting] = 0;
      }
      if (breakdownLikelihoods[elementName][setting] < MIN_LIKELIHOOD && contributingElementKeys.has(elementName)) {
        breakdownLikelihoods[elementName][setting] = MIN_LIKELIHOOD;
      } else if (!contributingElementKeys.has(elementName)) {
        breakdownLikelihoods[elementName][setting] = 1.0;
      }
    });
    breakdownLikelihoods[elementName] = normalizeProbabilities(breakdownLikelihoods[elementName]);
  });

  MY_JUGGLER_V_SETTINGS_NAMES.forEach(setting => {
    let product = 1.0;
    contributingElementKeys.forEach(key => product *= breakdownLikelihoods[key][setting]);
    overallLikelihoods[setting] = product;
  });

  if (playedGames > 0) {
    observedRates["BIG確率"] = playedBigCount > 0 ? `1/${(playedGames / playedBigCount).toFixed(1)}` : "-";
    observedRates["REG確率"] = playedRegCount > 0 ? `1/${(playedGames / playedRegCount).toFixed(1)}` : "-";
    if (grapeCount > 0) observedRates["ブドウ🍇 確率"] = `1/${(playedGames / grapeCount).toFixed(2)}`;
    if (!isIm && nonDuplicateCherryCount > 0) observedRates["非重複チェリー🍒 確率"] = `1/${(playedGames / nonDuplicateCherryCount).toFixed(1)}`;
  }

  // Calculate estimated payout
  let estimatedPayout: number | null = null;
  if (inputs.currentNetMedals !== null && playedGames > 0) {
    estimatedPayout = inputs.currentNetMedals;
  } else if (playedGames > 0) {
    const replayCount = playedGames / 7.3;
    const investment = playedGames * 3;
    const idealTable = isIm ? IM_JUGGLER_EX_IDEAL_RATES : GOGO_JUGGLER_3_IDEAL_RATES;

    let grapeCountForCalc = inputs.bellCount;
    if (inputs.bellCount <= 0) {
        grapeCountForCalc = playedGames * idealTable[KingHanaHanaSetting.SETTING_1].grape;
    }

    const triggerCherryTotal = inputs.cherryBigCount + inputs.cherryRegCount;
    let cherryCountForCalc = nonDuplicateCherryCount + triggerCherryTotal;
    if (cherryCountForCalc <= 0) {
        // Fallback for cherry (approximate)
        cherryCountForCalc = playedGames / 33; 
    }

    // Payouts
    // I'm Juggler EX: BIG 252, REG 96
    // GoGo Juggler 3: BIG 240, REG 96
    const bigMedals = isIm ? 252 : 240;
    const regMedals = 96;

    const payoutValue = (bigMedals * playedBigCount) + 
                        (regMedals * playedRegCount) + 
                        (8 * grapeCountForCalc) + 
                        (2 * cherryCountForCalc) + 
                        (3 * replayCount);
    estimatedPayout = payoutValue - investment;
  }

  return {
    overallProbabilities: normalizeProbabilities(overallLikelihoods),
    breakdownProbabilities: breakdownLikelihoods,
    activeElementKeys: [...contributingElementKeys],
    observedRates,
    estimatedPayout
  };
};

