declare const html2canvas: any;

interface ScenarioResultsDisplayPropsExtended extends GenericResultsDisplayProps {
  gameMode: GameMode;
  kingHanaHanaInputs?: KingHanaHanaSInput;
  hanaHanaHououInputs?: HanaHanaHououInput;
